// Repairs common speech-recognition slips for app names and the wake word before commands are parsed.
function repairSpoken(text:string){return text.replace(/^\s*(?:hey |ok |okay )?(?:jarvis|jarvice|travis|service)[,.!?]?\s+/i,'').replace(/\b(open|launch|start)(?: my| the)? (?:cool|strong|crome|chrom|krome|rome|grown|chrono|chrome browser|google chrome|crumb|crow)\b/gi,'$1 Chrome').replace(/\b(open|launch|start)(?: my| the)? (?:you tube|youtub|u tube)\b/gi,'$1 YouTube').replace(/\b(open|launch|start)(?: my| the)? (?:v s code|vs coat|vias code|visual studio)\b/gi,'$1 VS Code');}
// Long answers are read on screen; only the first sentences are spoken so JARVIS returns to listening quickly.
function spokenSummary(text:string,limit:number){const clean=text.replace(/[*#`>_~|-]{2,}|[*#`>]/g,' ').replace(/\s+/g,' ').trim();if(clean.length<=limit)return clean;const cut=clean.slice(0,limit);const end=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('? '),cut.lastIndexOf('! '),cut.lastIndexOf('؟ '));return (end>40?cut.slice(0,end+1):cut)+' The rest is on screen.';}
