async function handleVoiceTranscript(transcript:string){
  try{await runUserText(transcript,{isTrusted:true},true);await converse();}
  catch{toast('I could not complete that request. Check the message on screen for details.');try{await speak('I could not complete that request. Please check the screen for details.');}catch(error){toast('Speech failed: '+String(error));}}
  finally{try{await resumeWake();}catch(error){toast('Wake-word listener failed: '+String(error));}}
}
function overviewLayout(){return {version:1 as const,sides:{...overviewSide},order:[...overviewOrder],pinned:overviewPinned,hidden:overviewHidden,extras:[...overviewExtras] as ('activity'|'priority'|'research')[]};}
async function persistOverviewLayout(task?:UserTask){await state.preferences(SettingsSchema.parse({...state.settings,overviewLayout:overviewLayout()}),task,false);}
function sideFor(id:OverviewPanelId):'left'|'right'{return overviewSide[id]??(['profile','system-resources','security','development-tools'].includes(id)?'left':'right');}
function leastLoadedOverviewSide(except?:OverviewPanelId):'left'|'right'{const optional=new Set<OverviewPanelId>(['activity','priority','research']);const active=overviewOrder.filter(id=>id!==except&&(!optional.has(id)||overviewExtras.has(id as 'activity'|'priority'|'research')));const left=active.filter(id=>sideFor(id)==='left').length,right=active.length-left;return left<right?'left':'right';}
function moveOverviewPanel(id:OverviewPanelId,side:'left'|'right'){
  overviewSide[id]=side;
  const remaining=overviewOrder.filter(panel=>panel!==id);
  let insert=remaining.filter(panel=>sideFor(panel)===side).length;
  if(side==='left')insert=Math.min(insert,remaining.filter(panel=>sideFor(panel)==='left').length);
  else insert=remaining.filter(panel=>sideFor(panel)==='left').length+remaining.filter(panel=>sideFor(panel)==='right').length;
  remaining.splice(insert,0,id);overviewOrder=remaining;
}
async function overviewCommand(input:string,task?:UserTask):Promise<string|null>{
  const text=normalizeUtterance(input);
  if(/\b(?:show|add|open) (?:the )?(?:recent )?(?:research|research results)(?: panel)?(?: in| on) (?:the )?overview\b/.test(text)){overviewExtras.add('research');moveOverviewPanel('research',leastLoadedOverviewSide('research'));overviewHidden=false;overviewFocus='research';overviewAnimateNextRender=true;await persistOverviewLayout(task);return 'The latest local web research result is now in the Overview.';}
  if(/\b(?:hide|remove|close) (?:the )?(?:recent )?(?:research|research results)(?: panel)? from (?:the )?overview\b/.test(text)){overviewExtras.delete('research');if(overviewFocus==='research')overviewFocus=null;if(overviewPinned==='research')overviewPinned=null;await persistOverviewLayout(task);return 'The research panel has been removed from the Overview.';}
  if(/\b(?:show|add|open) (?:the )?(?:recent )?activity(?: panel)?(?: in| on) (?:the )?overview\b|\bshow recent activity\b/.test(text)){overviewExtras.add('activity');moveOverviewPanel('activity',leastLoadedOverviewSide('activity'));overviewHidden=false;overviewFocus='activity';await persistOverviewLayout(task);overviewAnimateNextRender=true;return 'Recent local activity is now in the Overview.';}
  if(/\b(?:hide|remove|close) (?:the )?(?:recent )?activity(?: panel)? from (?:the )?overview\b/.test(text)){overviewExtras.delete('activity');if(overviewFocus==='activity')overviewFocus=null;if(overviewPinned==='activity')overviewPinned=null;await persistOverviewLayout(task);return 'The recent activity panel has been removed from the Overview.';}
  if(/\b(?:show|add|open) (?:the )?(?:high priority|urgent|overdue|priority queue)(?: tasks?)?(?: panel)?(?: in| on)?(?: the)? overview\b|\bshow (?:me )?(?:my )?(?:high priority|urgent|overdue) tasks\b/.test(text)){overviewExtras.add('priority');moveOverviewPanel('priority',leastLoadedOverviewSide('priority'));overviewHidden=false;overviewFocus='priority';await persistOverviewLayout(task);overviewAnimateNextRender=true;return 'The local priority queue is now in the Overview, with overdue tasks ranked first.';}
  if(/\b(?:hide|remove|close) (?:the )?(?:high priority|urgent|overdue|priority queue)(?: tasks?)?(?: panel)? from (?:the )?overview\b/.test(text)){overviewExtras.delete('priority');if(overviewFocus==='priority')overviewFocus=null;if(overviewPinned==='priority')overviewPinned=null;await persistOverviewLayout(task);return 'The priority queue has been removed from the Overview.';}
  if(/\b(hide|clear) (everything|all panels|all widgets)\b|\bhide everything\b|\bhide all panels\b/.test(text)||/اخفي.*(كل|الكل)/.test(text)){overviewHidden=true;overviewFocus=null;await persistOverviewLayout(task);syncOverviewCanvas();return 'I’ve hidden the overview cards and kept the JARVIS centerpiece and globe in view. Say “restore overview” to bring them back.';}
  if(/\b(restore|show|bring back) (everything|all panels|overview panels)\b|\brestore overview\b|\bput everything back\b/.test(text)||/(رجع|اظهر|اعرض).*(اللوحات|كل حاجه)/.test(text)){overviewHidden=false;overviewFocus=null;overviewPinned=null;for(const id of overviewPanelIds)delete overviewSide[id];overviewOrder=[...overviewPanelIds];await persistOverviewLayout(task);overviewAnimateNextRender=true;syncOverviewCanvas(true);return 'The overview panels are restored to their default arrangement.';}
  if(/\b(keep|pin) (this|that|it) visible\b|\bkeep this visible\b/.test(text)||/(خلي|سيب).*(ده|دي|دا).*(ظاهر|باين)/.test(text)){if(!overviewFocus)return 'Which overview panel should I keep visible?';overviewPinned=overviewFocus;await persistOverviewLayout(task);syncOverviewCanvas();return 'I’ll keep the focused overview panel highlighted.';}
   const direction=text.match(/\b(?:put|move) (?:this|that|it) (?:on|to) (?:the )?(left|right)\b/);const arabicDirection=text.match(/(?:حط|انقل).*(ده|دي|دا).*(يمين|شمال)/)||text.match(/\u062d\u0637.*\u062f\u0647.*(\u064a\u0645\u064a\u0646|\u0634\u0645\u0627\u0644)/);if(direction||arabicDirection){if(!overviewFocus)return 'Which overview panel should I move?';const side=(direction?.[1]??(arabicDirection?.[2]==='يمين'||arabicDirection?.[1]==='\u064a\u0645\u064a\u0646'?'right':'left')) as 'left'|'right';moveOverviewPanel(overviewFocus,side);overviewHidden=false;await persistOverviewLayout(task);overviewAnimateNextRender=true;syncOverviewCanvas(true);return `Moved the focused panel to the ${side} overview column.`;}
   if(/\b(show|focus|bring up) (me )?(my )?(cpu|ram|system resources|system monitor|metrics)\b/.test(text)||/\bcpu and ram\b/.test(text)||/(وريني|اظهر|اعرض).*(المعالج|الرام|موارد النظام)/.test(text)||/\u0648\u0631\u064a\u0646\u064a.*(?:\u0627\u0644\u0645\u0639\u0627\u0644\u062c|\u0627\u0644\u0631\u0627\u0645)/.test(text)){overviewHidden=false;overviewFocus='system-resources';render();return 'System resources are in focus, using the latest available local readings.';}
  if(/\b(show|focus|bring up) (me )?(my )?(project|projects|project progress)\b/.test(text)||/(وريني|اظهر|اعرض).*(المشاريع|مشاريعي)/.test(text)){overviewHidden=false;overviewFocus='projects';render();return 'Your active-project panel is in focus.';}
  if(/\b(show|focus|bring up) (me )?(my )?(tasks|reminders|schedule|briefing|security|profile|development tools)\b/.test(text)){
    const id:OverviewPanelId=/tasks|reminders/.test(text)?'tasks':/schedule/.test(text)?'schedule':/briefing/.test(text)?'briefing':/security/.test(text)?'security':/profile/.test(text)?'profile':'development-tools';overviewHidden=false;overviewFocus=id;render();return `${id.replaceAll('-',' ')} is in focus.`;
  }
  if(/\b(make (this|that|it) bigger|expand (this|that|it))\b/.test(text)){if(!overviewFocus)return 'Which overview panel should I expand?';render();return 'The focused panel has been given more space in its column.';}
  if(/\b(show|focus) the other one\b/.test(text)){if(!overviewFocus)return 'Which panel should I switch from?';const index=overviewPanelIds.indexOf(overviewFocus);overviewFocus=overviewPanelIds[(index+1)%overviewPanelIds.length];overviewHidden=false;render();return 'I’ve focused the next overview panel.';}
  return null;
}
function securityRows() { const items:[string,boolean|null|undefined][] = [['Windows Defender',security?.defender],['Real-time protection',security?.realTime],['Windows Firewall',security?.firewall]]; return `<div class="security-rows">${items.map(([label,value])=>`<div><span><i class="${value===true?'ok':value===false?'warning':'unknown'}"></i>${label}</span><strong class="${value===true?'text-green':value===false?'text-warning':'muted'}">${value===true?'Active':value===false?'Inactive':'Unknown'}</strong></div>`).join('')}</div>`; }
function securityCard() { return panel('Cybersecurity center','shield', `<div class="security-body"><div class="security-emblem">${icon('shield')}${icon('lock')}</div>${securityRows()}</div><div class="panel-note">${security?.error?esc(security.error):security?'Verified using Windows security providers.':'Protection status requires a native Windows reading.'}</div>`, link('Details','security')); }
function toolsCard() { return panel('Development environment','code', `<div class="tools">${['VS Code','Git','Node.js','Python','Docker'].map((name,i)=>{const tool=tools.find(t=>t.name===name);return `<div class="tool-tile"><span class="tool-logo logo-${i}">${['VS','G','JS','Py','D'][i]}</span><span>${name}</span><small class="${tool?.running?'text-green':''}"><i class="${tool?.running?'ok':tool?.installed?'installed':'unknown'}"></i>${tool?.running?'Running':tool?.installed?'Installed':tool?'Unavailable':'Unknown'}</small></div>`;}).join('')}</div>`); }
