function briefing() { const tasks=state.list('task').filter(t=>!t.done);const events=state.list('event').filter(e=>e.dueAt&&new Date(e.dueAt).toDateString()===new Date().toDateString());return `<div class="briefing-intro">${greet()}<p>Here’s your day, at a glance.</p></div><div class="briefing-lines"><div>${icon('calendar')}<span><strong>${events.length}</strong> appointments today</span></div><div>${icon('task')}<span><strong>${tasks.length}</strong> tasks waiting for you</span></div><div>${icon('code')}<span><strong>${state.list('project').length}</strong> projects in your workspace</span></div><div>${icon('shield')}<span>${security?.defender===true?'Defender protection active':'Security status '+(security?.defender===false?'needs attention':'not yet verified')}</span></div></div><button class="briefing-button" data-action="briefing">${icon('send')} Generate my briefing ${icon('arrow')}</button>`; }
