function activityPanel(){const rows=state.list('activity').slice(0,3);const body=rows.length?`<div class="activity-list">${rows.map(row=>`<div class="activity-row">${icon('history')}<div><strong>${esc(row.title)}</strong><p>${esc(row.body.slice(0,120))}</p></div><time>${dateTime(row.createdAt)}</time></div>`).join('')}</div>`:empty('history','No recent activity yet.','Local activity appears here after JARVIS workflows run.');return panel('Recent activity','history',body,'<button class="icon-button" data-action="overview-hide-activity" aria-label="Remove recent activity panel">×</button>');}
function priorityPanel(){const urgent=state.list('task').filter(task=>!task.done).sort((a,b)=>Number(!(a.dueAt&&Date.parse(a.dueAt)<Date.now()))-Number(!(b.dueAt&&Date.parse(b.dueAt)<Date.now()))||({high:0,medium:1,low:2}[a.priority]-{high:0,medium:1,low:2}[b.priority])||(a.dueAt||'z').localeCompare(b.dueAt||'z')).slice(0,3);const body=urgent.length?`<div class="task-list">${urgent.map(r=>`<div class="task-row"><input type="checkbox" aria-label="Complete ${esc(r.title)}" data-complete="${r.id}"><button class="record-title" data-edit="${r.id}"><span>${esc(r.title)}</span>${r.dueAt?`<small>${dateTime(r.dueAt)}</small>`:''}</button><span class="priority ${r.priority}">${r.priority}</span></div>`).join('')}</div>`:empty('task','Nothing urgent right now.','No open tasks need immediate attention.');return panel('Priority queue','task',body,'<button class="icon-button" data-action="overview-hide-priority" aria-label="Remove priority queue panel">×</button>');}
function dashboard() { return `<div class="overview-viewport"><div class="overview-canvas" data-overview-focus="${overviewFocus??''}" data-overview-pinned="${overviewPinned??''}" data-overview-hidden="${overviewHidden}"><div class="dashboard-heading"><div><span class="eyebrow">COMMAND CENTER</span><h1>Your personal universe<span>.</span></h1></div>${alertsStrip()}<span class="workspace-status"><i class="status-dot"></i>${native?'Local system connected':'Browser preview'}</span>${overviewHidden?'<button class="text-link" data-action="overview-restore">Restore overview panels</button>':''}</div><div class="dashboard-grid"><div class="dashboard-stack">${profileCard()}${systemCard()}${securityCard()}${toolsCard()}</div>${core()}<div class="dashboard-stack">${panel('Today’s briefing','calendar',briefing(),'<span class="tiny-label">DAILY INTELLIGENCE</span>')}${panel('Active projects','code',projectsWidget(),link('View all','projects'))}${panel('Today’s schedule','calendar',eventRows(3),link('Calendar','calendar'))}${panel('Tasks & reminders','task',taskRows(3),link('View all','tasks'))}${overviewExtras.has('activity')?activityPanel():''}</div></div></div></div>`; }
function applyOverviewSides(content:HTMLElement,animate=false){const stacks=content.querySelectorAll<HTMLElement>('.dashboard-stack');if(stacks.length!==2)return;const left=stacks[0],right=stacks[1];if(overviewExtras.has('priority')&&!content.querySelector('[data-overview-panel="priority"]'))right.insertAdjacentHTML('beforeend',priorityPanel());const before=new Map<OverviewPanelId,DOMRect>();if(animate)for(const id of overviewPanelIds){const node=content.querySelector<HTMLElement>(`[data-overview-panel="${id}"]`);if(node)before.set(id,node.getBoundingClientRect());}const ordered=overviewPinned?[overviewPinned,...overviewOrder.filter(id=>id!==overviewPinned)]:overviewOrder;for(const id of ordered){const node=content.querySelector<HTMLElement>(`[data-overview-panel="${id}"]`);if(node){(sideFor(id)==='left'?left:right).append(node);const handle=node.querySelector<HTMLElement>('.panel-heading');if(handle){handle.draggable=true;handle.dataset.overviewDrag=id;handle.title='Drag this panel to another column';}}}for(const stack of [left,right]){const children=[...stack.querySelectorAll<HTMLElement>(':scope > .panel')];stack.classList.toggle('has-overflow-panels',children.length>4||(overviewFocus!==null&&children.some(node=>node.dataset.overviewPanel===overviewFocus)));const rows=children.map(node=>node.dataset.overviewPanel===overviewFocus?'1.8fr':'1fr');stack.style.gridTemplateRows=children.length===4&&overviewFocus===null?'':rows.join(' ');}if(animate&&!state.settings.reducedMotion&&!state.settings.lowPower&&!matchMedia('(prefers-reduced-motion: reduce)').matches)for(const id of overviewPanelIds){const node=content.querySelector<HTMLElement>(`[data-overview-panel="${id}"]`),old=before.get(id);if(node&&old){const box=node.getBoundingClientRect(),dx=old.left-box.left,dy=old.top-box.top;if(Math.abs(dx)+Math.abs(dy)>1)void node.animate([{transform:`translate(${dx}px, ${dy}px)`},{transform:'translate(0, 0)'}],{duration:260,easing:'cubic-bezier(.2,.75,.25,1)'}).finished.catch(()=>{});}}}
function researchPanel(){const row=state.list('activity').find(r=>r.title==='Web research completed');const body=row?'<div class="research-result"><p>'+esc(row.body.slice(0,220))+'</p><small class="muted">Saved locally '+dateTime(row.createdAt)+'. Check cited sources before relying on conclusions.</small></div>':empty('search','No saved research yet.','Run a cited web research request first.');return panel('Recent research','search',body,'<button class="icon-button" data-action="overview-hide-research" aria-label="Remove research panel">×</button>').replace('<section ','<section data-overview-panel="research" ');}
function syncOverviewCanvas(animate=false){const content=document.querySelector<HTMLElement>('#content'),canvas=content?.querySelector<HTMLElement>('.overview-canvas');if(!content||!canvas)return;canvas.dataset.overviewFocus=overviewFocus??'';canvas.dataset.overviewPinned=overviewPinned??'';canvas.dataset.overviewHidden=String(overviewHidden);applyOverviewSides(content,animate);}
