async function runWorkspace(name:string,task?:UserTask) {
  if(!native)throw new Error('Workspace control is available in the Windows desktop app.');
  const preset=state.settings.workspacePresets.find(p=>p.name.toLowerCase()===name.toLowerCase());
  if(!preset)throw new Error(`No saved workspace named “${name}” was found.`);
  const monitors=await command<{key:string;label:string}[]>('monitor_list');
  const resolved=preset.placements.map(item=>{const index=monitorIndex(item.monitor,monitors.length);if(index===null)throw new Error(`Workspace “${preset.name}” needs unavailable display “${item.monitor}”. Nothing was opened.`);return {...item,monitorKey:monitors[index].key,label:monitors[index].label};}).sort((a,b)=>Number(a.application==='jarvis')-Number(b.application==='jarvis'));
  const completed:string[]=[];
  try {
    for(const item of resolved){
      if(item.application==='jarvis'){
        await state.preferences(SettingsSchema.parse({...state.settings,monitorKey:item.monitorKey}),task);
        go('dashboard');
        await openOverviewFullscreen(()=>go('hud'),item.monitorKey);
      } else await command('app_window_control',{application:item.application,operation:'open',monitorKey:item.monitorKey},task);
      completed.push(`${item.application} on ${item.label}`);
    }
  } catch(error) {
    throw new Error(`Workspace partially applied (${completed.join('; ')||'no placements completed'}). No applications were closed. ${error instanceof Error?error.message:'A Windows action failed.'}`);
  }
  return `Workspace “${preset.name}” opened: ${completed.join('; ')}. No applications were closed.`;
}
