// Live alerts: the most important things right now, recomputed from local data on every refresh.
function alertItems(){const now=Date.now(),items:{level:'critical'|'warn'|'info';icon:string;text:string}[]=[];
  const open=state.list('task').filter(t=>!t.done);const overdue=open.filter(t=>t.dueAt&&Date.parse(t.dueAt)<now);
  if(overdue.length)items.push({level:'critical',icon:'task',text:`${overdue.length} overdue task${overdue.length>1?'s':''}: ${overdue[0].title}`});
  const next=state.list('event').filter(e=>e.dueAt&&Date.parse(e.dueAt)>now).sort((a,b)=>a.dueAt.localeCompare(b.dueAt))[0];
  if(next){const mins=Math.round((Date.parse(next.dueAt)-now)/60000);if(mins<=180)items.push({level:mins<=30?'warn':'info',icon:'calendar',text:`${next.title} in ${mins<60?mins+' min':Math.round(mins/60)+' h'}`});}
  const soon=open.filter(t=>t.dueAt&&Date.parse(t.dueAt)>=now&&Date.parse(t.dueAt)-now<3600000);if(soon.length)items.push({level:'warn',icon:'task',text:`Due within the hour: ${soon[0].title}`});
  if(telemetry?.cpu!=null&&telemetry.cpu>85)items.push({level:'warn',icon:'cpu',text:`CPU running hot at ${Math.round(telemetry.cpu)}%`});
  if(telemetry&&telemetry.ramTotal>0&&telemetry.ramUsed/telemetry.ramTotal>0.9)items.push({level:'warn',icon:'cpu',text:`Memory at ${Math.round(telemetry.ramUsed/telemetry.ramTotal*100)}%`});
  if(telemetry?.battery!=null&&telemetry.battery<20&&!telemetry.charging)items.push({level:'critical',icon:'power',text:`Battery low: ${telemetry.battery}%`});
  if(security?.defender===false||security?.realTime===false)items.push({level:'critical',icon:'shield',text:'Real-time protection is off'});
  const unread=state.list('notification').filter(n=>!n.done).length;if(unread)items.push({level:'info',icon:'bell',text:`${unread} new notification${unread>1?'s':''}`});
  if(weather)items.push({level:'info',icon:'cloud',text:`${state.settings.location}: ${Math.round(weather.temperature)}°C, ${weather.description}`});
  if(!items.length)items.push({level:'info',icon:'shield',text:'All systems nominal. Nothing needs your attention.'});
  return items;}
function alertsStrip(){return `<div class="hud-alerts" id="hud-alerts" role="status" aria-live="polite">${alertItems().slice(0,4).map((a,i)=>`<span class="hud-alert ${a.level}" style="--i:${i}">${icon(a.icon)}${esc(a.text)}</span>`).join('')}</div>`;}
let lastAlerts='';
function refreshAlerts(){const el=document.querySelector('#hud-alerts');if(!el)return;const html=alertsStrip();if(html===lastAlerts)return;lastAlerts=html;el.outerHTML=html;}
// Proactive assistant: like the films, JARVIS speaks up on its own about what is coming next.
