  fillDisplay(page?.title??topic,hero+(ai?`<div class="dsp-md">${mdLite(ai.replace(/^\s*(?:ACTION|Say)\s*:.*$/gim,''))}</div>`:''));
  const first=(page?.extract??ai.replace(/[#*|`-]/g,' ')).split(/(?<=[.!?؟])\s/)[0]?.trim().slice(0,220);
