function weatherDetails(){if(!weather)return;let forecast:{time?:string[];temperature_2m_max?:number[];temperature_2m_min?:number[]}={};try{forecast=JSON.parse(weather.forecast??'{}');}catch{}const d=document.querySelector<HTMLDialogElement>('#editor')!;if(d.open)d.close();d.innerHTML=`<div class="dialog-heading"><h2>Weather · ${esc(state.settings.location)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button></div><h2>${weather.temperature}°C · ${esc(weather.description)}</h2><p class="muted">Last successful update: ${dateTime(weather.at)}. Cached readings remain available offline.</p>${(forecast.time??[]).map((day,i)=>`<div class="weather-forecast-row"><span>${esc(day)}</span><strong>${esc(forecast.temperature_2m_min?.[i])}° / ${esc(forecast.temperature_2m_max?.[i])}°C</strong></div>`).join('')}<p class="muted small">Weather data: Open-Meteo. Forecast values are model estimates.</p><button class="secondary-button" data-action="weather-refresh">Refresh weather</button>`;d.showModal();}
